using System;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
using System.Web.Script.Serialization;
public sealed class ActionEditorPanel : Panel {
 readonly bool step;string kind="Disabled";
 TextBox application=new TextBox(),arguments=new TextBox(),directory=new TextBox(),target=new TextBox(),combination=new TextBox();ComboBox mouse=new ComboBox();NumericUpDown amount=new NumericUpDown(),wait=new NumericUpDown();Button sequence;List<ActionSpec> steps=new List<ActionSpec>();TableLayoutPanel rows;bool advanced;public bool AdvancedExpanded {get{return advanced;}} public event EventHandler AdvancedChanged;public void SetAdvancedExpanded(bool value){advanced=value;SetAction(kind);if(AdvancedChanged!=null)AdvancedChanged(this,EventArgs.Empty);}
 public ActionEditorPanel(bool isStep){step=isStep;AutoSize=false;Height=200;Dock=DockStyle.Top;rows=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=2};rows.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,145));rows.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(rows);mouse.FlatStyle=FlatStyle.Flat;mouse.DropDownStyle=ComboBoxStyle.DropDownList;mouse.Items.AddRange(new object[]{"LeftClick","RightClick","DoubleClick","Scroll"});mouse.FormattingEnabled=true;mouse.Format+=(s,e)=>{switch(Convert.ToString(e.ListItem)){case "LeftClick":e.Value=UiText.Get("Левый щелчок");break;case "RightClick":e.Value=UiText.Get("Правый щелчок");break;case "DoubleClick":e.Value=UiText.Get("Двойной щелчок");break;case "Scroll":e.Value=UiText.Get("Прокрутка");break;}};mouse.SelectedItem="LeftClick";amount.Minimum=-100;amount.Maximum=100;amount.Value=1;wait.Minimum=0;wait.Maximum=10000;sequence=new Button{Text=UiText.Get("Редактировать шаги…"),Dock=DockStyle.Fill};sequence.Click+=(s,e)=>{using(var f=new SequenceEditorForm(steps)){if(f.ShowDialog(FindForm())==DialogResult.OK){steps=f.Result;sequence.Text=UiText.Get("Редактировать шаги… (")+steps.Count+")";}}};SetAction("Disabled");}
 void Row(string title,Control value){int n=rows.RowCount++;rows.RowStyles.Add(new RowStyle(SizeType.Absolute,38*WindowLayout.ScaleFor(this)));rows.Controls.Add(new Label{Text=title,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,n);value.Dock=DockStyle.Fill;int unit=(int)(4*WindowLayout.ScaleFor(this));value.Margin=new Padding(0,unit,unit,unit);rows.Controls.Add(value,1,n);}
 void CaptionRow(string title,Control value){Row(title,value);rows.RowStyles[rows.RowCount-1].Height=46*WindowLayout.ScaleFor(this);}
 Control Picker(TextBox value,int type){return WindowLayout.PathPicker(value,(s,e)=>{if(type==1){using(var d=new FolderBrowserDialog{Description=UiText.Get("Выберите папку")})if(d.ShowDialog()==DialogResult.OK)value.Text=d.SelectedPath;}else using(var d=new OpenFileDialog{Filter=type==0?UiText.Get("Приложение (*.exe)|*.exe"):UiText.Get("Файл (*.*)|*.*"),Title=type==0?UiText.Get("Выберите приложение .exe"):UiText.Get("Выберите файл")})if(d.ShowDialog()==DialogResult.OK)value.Text=d.FileName;});}
 public void SetAction(string value){kind=value;rows.ColumnStyles[0].Width=(value=="LaunchApplication"||value=="OpenTargetApplication"||(step&&value=="Key")?300:145)*WindowLayout.ScaleFor(this);rows.Controls.Clear();rows.RowStyles.Clear();rows.RowCount=0;switch(kind){case "OpenTargetApplication":case "LaunchApplication":CaptionRow(UiText.Get("Какое приложение кнопка должна открыть"),Picker(application,0));var expand=new Button{Text=(advanced?"▾ ":"▸ ")+UiText.Get("Дополнительные параметры запуска")};expand.Click+=(s,e)=>SetAdvancedExpanded(!advanced);Row("",expand);if(advanced){Row(UiText.Get("Аргументы"),arguments);Row(UiText.Get("Рабочая папка"),Picker(directory,1));}Row("",new Label{Text=UiText.Get("Показать окно или запустить EXE."),AutoSize=false});break;case "OpenTarget":Row(UiText.Get("Файл / папка / URL"),Picker(target,2));var choose=new Button{Text=UiText.Get("Выбрать папку…")};choose.Click+=(s,e)=>{using(var d=new FolderBrowserDialog())if(d.ShowDialog()==DialogResult.OK)target.Text=d.SelectedPath;};Row("",choose);Row("",new Label{Text=UiText.Get("Файл или папка открываются штатной программой; ссылки — только http / https.")});break;case "Mouse":Row(UiText.Get("Действие мыши"),mouse);Row(UiText.Get("Прокрутка"),amount);Row("",new Label{Text=UiText.Get("Щелчок только в текущем положении курсора. + вверх, − вниз (деления колеса).")});break;case "Sequence":Row(UiText.Get("Последовательность"),sequence);Row("",new Label{Text=UiText.Get("1–32 шага; ожидание до 10 секунд за шаг, суммарно до 60 секунд.")});break;case "Wait":Row(UiText.Get("Ожидание, мс"),wait);break;case "Key":if(step)CaptionRow(UiText.Get("Клавиша или сочетание клавиш"),combination);break;}float height=8*WindowLayout.ScaleFor(this);foreach(RowStyle row in rows.RowStyles)height+=row.Height;Height=Math.Max(1,(int)height);}
 public void Load(ActionSpec a){application.Text=a.ApplicationPath??"";arguments.Text=a.Arguments??"";directory.Text=a.WorkingDirectory??"";target.Text=a.Target??"";mouse.SelectedItem=a.MouseAction??"LeftClick";amount.Value=Math.Max(-100,Math.Min(100,a.ScrollAmount));wait.Value=Math.Max(0,Math.Min(10000,a.WaitMilliseconds));combination.Text=a.Key;steps=CloneSteps(a.Steps);sequence.Text=UiText.Get("Редактировать шаги… (")+steps.Count+")";SetAction(a.Action);}
 public void Store(ActionSpec a){a.ApplicationPath=application.Text;a.Arguments=arguments.Text;a.WorkingDirectory=directory.Text;a.Target=target.Text;a.MouseAction=Convert.ToString(mouse.SelectedItem);a.ScrollAmount=(int)amount.Value;a.WaitMilliseconds=kind=="Wait"?(int)wait.Value:0;a.Steps=kind=="Sequence"?CloneSteps(steps):null;if(step)a.Key=combination.Text;}
 public static List<ActionSpec> CloneSteps(List<ActionSpec> source){return source==null?new List<ActionSpec>():new JavaScriptSerializer().Deserialize<List<ActionSpec>>(new JavaScriptSerializer().Serialize(source));}
 public static string Label(string action){switch(action){case "LaunchApplication":return UiText.Get("Открыть приложение");case "OpenTarget":return UiText.Get("Открыть файл / папку / ссылку");case "Mouse":return UiText.Get("Мышь (текущий курсор)");case "Sequence":return UiText.Get("Последовательность");case "Wait":return UiText.Get("Ожидание");case "Key":return UiText.Get("Клавиша / сочетание");case "OpenTargetApplication":return UiText.Get("Открыть приложение");case "Disabled":return UiText.Get("Без действия");default:return UiText.Get("Штатное действие");}}
}
public sealed class SequenceEditorForm : Form {
 Icon ownedIcon; List<ActionSpec> values;ListBox list=new ListBox();ComboBox action=new ComboBox();ActionEditorPanel edit=new ActionEditorPanel(true);bool loading;int current=-1;Label status=new Label();public List<ActionSpec> Result {get{return ActionEditorPanel.CloneSteps(values);}}
 public SequenceEditorForm(List<ActionSpec> source){ownedIcon=AppIcon.Create();Icon=ownedIcon;values=ActionEditorPanel.CloneSteps(source);Text=UiText.Get("Последовательность действий");Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.None;Size=new Size(860,510);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=56,Padding=new Padding(12,4,0,0)};Controls.Add(footer);AddButton(footer,UiText.Get("Готово"),()=>{try{Store();ActionValidation.Validate(new ActionSpec{Action="Sequence",Steps=values},false);DialogResult=DialogResult.OK;}catch(Exception e){status.Text=e.Message;}});AddButton(footer,UiText.Get("Отмена"),()=>{DialogResult=DialogResult.Cancel;});status.Dock=DockStyle.Bottom;status.Height=45;Controls.Add(status);var body=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(12)};body.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,245));body.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(body);body.BringToFront();var left=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};left.RowStyles.Add(new RowStyle(SizeType.Percent,100));left.RowStyles.Add(new RowStyle(SizeType.Absolute,44));left.RowStyles.Add(new RowStyle(SizeType.Absolute,44));body.Controls.Add(left);list.Dock=DockStyle.Fill;list.IntegralHeight=false;left.Controls.Add(list);var addrow=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};left.Controls.Add(addrow);AddButton(addrow,UiText.Get("Добавить"),AddStep);AddButton(addrow,UiText.Get("Удалить"),RemoveStep);var order=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};left.Controls.Add(order);AddButton(order,UiText.Get("Вверх"),()=>MoveStep(-1));AddButton(order,UiText.Get("Вниз"),()=>MoveStep(1));var right=new Panel{Dock=DockStyle.Fill,AutoScroll=true};body.Controls.Add(right);edit.Dock=DockStyle.Top;right.Controls.Add(edit);action.Dock=DockStyle.Top;action.DropDownStyle=ComboBoxStyle.DropDownList;action.Items.AddRange(new object[]{"Key","LaunchApplication","OpenTarget","Mouse","Wait"});action.FormattingEnabled=true;action.Format+=(s,e)=>e.Value=ActionEditorPanel.Label(Convert.ToString(e.ListItem));right.Controls.Add(action);action.SelectedIndexChanged+=(s,e)=>{if(!loading)edit.SetAction(Convert.ToString(action.SelectedItem));};list.SelectedIndexChanged+=(s,e)=>{if(loading)return;Store();current=list.SelectedIndex;LoadStep();};RefreshList(values.Count>0?0:-1);WindowLayout.ScaleAndFit(this,null);Shown+=(s,e)=>WindowLayout.Clamp(this);}
 void AddButton(Control parent,string title,Action click){var b=new Button{Text=title,Width=104,Height=34,Margin=new Padding(0,4,6,0)};b.Click+=(s,e)=>click();parent.Controls.Add(b);}
 void Store(){if(current<0||current>=values.Count)return;var a=values[current];a.Action=Convert.ToString(action.SelectedItem);edit.Store(a);}
 void LoadStep(){loading=true;if(current>=0&&current<values.Count){action.SelectedItem=values[current].Action=="OpenTargetApplication"?"LaunchApplication":values[current].Action;edit.Load(values[current]);}action.Enabled=edit.Enabled=current>=0;loading=false;}
 void RefreshList(int selection){loading=true;list.Items.Clear();for(int i=0;i<values.Count;i++)list.Items.Add((i+1)+". "+ActionEditorPanel.Label(values[i].Action));current=selection;list.SelectedIndex=selection;loading=false;LoadStep();}
 public void AddStep(){Store();if(values.Count>=32){status.Text=UiText.Get("Максимум 32 шага.");return;}values.Add(new ActionSpec{Action="Key"});RefreshList(values.Count-1);}
 public void RemoveStep(){if(current<0)return;values.RemoveAt(current);RefreshList(values.Count==0?-1:Math.Min(current,values.Count-1));}
 public void MoveStep(int direction){Store();int next=current+direction;if(current<0||next<0||next>=values.Count)return;var a=values[current];values.RemoveAt(current);values.Insert(next,a);RefreshList(next);}
 public void SetStep(ActionSpec a){if(current<0)return;values[current]=new JavaScriptSerializer().Deserialize<ActionSpec>(new JavaScriptSerializer().Serialize(a));LoadStep();}
 public void SelectStep(int index){list.SelectedIndex=index;}
 protected override void Dispose(bool disposing){base.Dispose(disposing);if(disposing&&ownedIcon!=null){ownedIcon.Dispose();ownedIcon=null;}}
}
